#pragma once
#include "WifiRadioTestModel.h"
#include <stdio.h>
namespace wifi_radio_test {
// These identify ONLY the board recording this CSV. They are not remote facts.
static const size_t kCsvLineCapacity = 4096;
struct CsvContext {const char* firmwareVersion="unknown";int64_t buildNumber=-1;int32_t resetReason=-1;int8_t usbPhyCompiled=-1,reduceTxPowerCompiled=-1;};
struct CsvWriter {
 char* out;size_t capacity,at=0;bool okay=true,first=true;
 void ch(char c){if(at+1<capacity)out[at++]=c;else okay=false;}
 void separator(){if(!first)ch(',');first=false;}
 void text(const char* value){separator();ch('"');if(value)for(const char*p=value;*p;++p){if(*p=='"')ch('"');ch(*p);}ch('"');}
 void number(int64_t value){separator();char s[28];snprintf(s,sizeof(s),"%lld",static_cast<long long>(value));for(const char*p=s;*p;++p)ch(*p);}
 size_t finish(){ch('\n');if(capacity)out[at<capacity?at:capacity-1]='\0';return okay?at:0;}
};
inline size_t csvHeader(char*out,size_t capacity){
 static const char header[]="local_recorder_firmware_version,local_recorder_build_number,local_recorder_reset_reason,local_recorder_usb_phy_compiled,local_recorder_reduce_tx_power_compiled,session,run,stage,distance,level,manual,local_mac,peer_mac,paired,local_started,remote_started,remote_report,remote_final,complete,reason,queue_overflow,config_mismatch,mac_telemetry_correlated,local_requested_raw,local_actual_raw,local_actual_valid,local_power_error,remote_requested_raw,remote_actual_raw,remote_actual_valid,remote_power_error,local_probe_tx_attempts,local_probe_api_accepted,local_probe_api_errors,local_mac_success,local_mac_errors,local_unique_rx,local_echoes,remote_probe_tx_attempts,remote_probe_api_accepted,remote_probe_api_errors,remote_mac_success,remote_mac_errors,remote_unique_rx,remote_echoes,local_to_remote_loss_permille,remote_to_local_loss_permille,comparison,local_clock_domain,remote_clock_domain,local_armed_at,local_started_at,local_ended_at,local_elapsed_ms,local_finished_at,remote_started_at,remote_ended_at,remote_elapsed_ms,local_timing_valid,remote_timing_valid,local_rssi_valid,local_rssi_last,local_rssi_min,local_rssi_max,local_rssi_at_local_clock,remote_rssi_valid,remote_rssi_last,remote_rssi_min,remote_rssi_max,remote_rssi_at_remote_clock,local_rtt_min_ms,local_rtt_max_ms,local_rtt_sum_ms,remote_rtt_min_ms,remote_rtt_max_ms,remote_rtt_sum_ms,local_restore_attempted,local_restore_requested_raw,local_restore_actual_raw,local_restore_actual_valid,local_restore_error,remote_restore_attempted,remote_restore_requested_raw,remote_restore_actual_raw,remote_restore_actual_valid,remote_restore_error,remote_restore_confirmed,channel,protocol,power_save,local_baseline_raw,remote_baseline_raw,local_echo_tx_attempts,local_echo_api_accepted,local_echo_api_errors,local_control_tx_attempts,local_control_api_accepted,local_control_api_errors,remote_echo_tx_attempts,remote_echo_api_accepted,remote_echo_api_errors,remote_control_tx_attempts,remote_control_api_accepted,remote_control_api_errors,comparison_reason,local_mac_telemetry_valid,remote_mac_telemetry_valid\n";
 if(capacity<sizeof(header)){if(capacity)out[0]='\0';return 0;}memcpy(out,header,sizeof(header));return sizeof(header)-1;
}
inline void csvMac(CsvWriter&w,const uint8_t*mac){char s[18];snprintf(s,sizeof(s),"%02X:%02X:%02X:%02X:%02X:%02X",mac[0],mac[1],mac[2],mac[3],mac[4],mac[5]);w.text(s);}
inline void csvPower(CsvWriter&w,const PowerResult&p,bool present){w.number(present?p.requestedRaw:-1);w.number(present&&p.actualValid?p.actualRaw:-1);w.number(present?p.actualValid:-1);w.number(present?p.error:-1);}
inline void csvCounts(CsvWriter&w,const Stats&s,bool present){w.number(present?s.txAttempts:-1);w.number(present?s.apiAccepted:-1);w.number(present?s.apiErrors:-1);w.number(present&&s.macTelemetryValid?s.macSuccess:-1);w.number(present&&s.macTelemetryValid?s.macErrors:-1);w.number(present?s.uniqueRx:-1);w.number(present?s.echoes:-1);}
inline void csvRssi(CsvWriter&w,const Stats&s,bool present){w.number(present?s.rssiValid:-1);w.number(present&&s.rssiValid?s.rssiLast:-1);w.number(present&&s.rssiValid?s.rssiMin:-1);w.number(present&&s.rssiValid?s.rssiMax:-1);w.number(present&&s.rssiValid?int64_t(s.rssiAt):-1);}
inline void csvRtt(CsvWriter&w,const Stats&s,bool present){w.number(present&&s.echoes?int64_t(s.rttMinMs):-1);w.number(present&&s.echoes?int64_t(s.rttMaxMs):-1);w.number(present&&s.echoes?int64_t(s.rttSumMs):-1);}
inline size_t csvRow(const Report&r,const CsvContext&context,char*out,size_t capacity){
 CsvWriter w{out,capacity};w.text(context.firmwareVersion);w.number(context.buildNumber);w.number(context.resetReason);w.number(context.usbPhyCompiled);w.number(context.reduceTxPowerCompiled);w.number(r.session);w.number(r.run);w.number(r.stage);w.text(distanceName(r.distance));w.text(levelName(r.level));w.number(r.manual);csvMac(w,r.localMac);csvMac(w,r.peerMac);
 w.number(r.paired);w.number(r.localStarted);w.number(r.remotePresent?r.remoteStarted:-1);w.number(r.remotePresent);w.number(r.remoteFinal);w.number(r.complete);w.number(uint8_t(r.reason));w.number(r.queueOverflow);w.number(r.configMismatch);w.number(r.local.macTelemetryValid||(r.remotePresent&&r.remote.macTelemetryValid)?r.telemetryCorrelated:-1);
 csvPower(w,r.localPower,true);csvPower(w,r.remotePower,r.remotePower.actualValid||r.remotePresent);csvCounts(w,r.local,true);csvCounts(w,r.remote,r.remotePresent);w.number(lossPermille(r,true));w.number(lossPermille(r,false));w.text(comparable(r)&&lossPermille(r,true)>=0&&lossPermille(r,false)>=0?"measured":"not_measured");
 w.number(r.local.clockDomain);w.number(r.remotePresent?int64_t(r.remote.clockDomain):-1);w.number(r.armedAt);w.number(r.localStarted?int64_t(r.local.startedAt):-1);w.number(r.localStarted?int64_t(r.local.endedAt):-1);w.number(r.local.timingValid?int64_t(uint32_t(r.local.endedAt-r.local.startedAt)):-1);w.number(r.finishedAt?r.finishedAt:int64_t(-1));w.number(r.remotePresent&&r.remoteStarted?int64_t(r.remote.startedAt):-1);w.number(r.remotePresent&&r.remoteStarted?int64_t(r.remote.endedAt):-1);w.number(r.remotePresent&&r.remote.timingValid?int64_t(uint32_t(r.remote.endedAt-r.remote.startedAt)):-1);w.number(r.local.timingValid);w.number(r.remotePresent?r.remote.timingValid:-1);
 csvRssi(w,r.local,true);csvRssi(w,r.remote,r.remotePresent);csvRtt(w,r.local,true);csvRtt(w,r.remote,r.remotePresent);
 w.number(r.localRestoreAttempted);csvPower(w,r.localRestore,r.localRestoreAttempted);w.number(r.remoteFinal?r.remoteRestoreAttempted:-1);csvPower(w,r.remoteRestore,r.remoteFinal&&r.remoteRestoreAttempted);w.number(r.remoteRestoreConfirmed);w.number(r.channel);w.number(r.protocol);w.number(r.powerSave);w.number(r.localBaselineRaw?r.localBaselineRaw:-1);w.number(r.remoteBaselineRaw?r.remoteBaselineRaw:-1);
 const Stats* kinds[2]={&r.local,&r.remote};for(unsigned i=0;i<2;++i){const Stats&s=*kinds[i];bool present=!i||r.remotePresent;w.number(present?s.echoTxAttempts:-1);w.number(present?s.echoApiAccepted:-1);w.number(present?s.echoApiErrors:-1);w.number(present?s.controlTxAttempts:-1);w.number(present?s.controlApiAccepted:-1);w.number(present?s.controlApiErrors:-1);}
 const char* why="valid";if(!r.localStarted||!r.remoteStarted)why="both_not_started";else if(!r.paired)why="not_paired";else if(!r.remotePresent)why="remote_unknown";else if(r.queueOverflow)why="queue_overflow";else if(r.configMismatch)why="config_mismatch";else if(!r.local.timingValid||!r.remote.timingValid||!r.complete)why="invalid_timing_or_incomplete";else if(!powerOkay(r.localPower)||!powerOkay(r.remotePower)||r.localPower.actualRaw!=r.remotePower.actualRaw)why="power_mismatch_or_unknown";else if(!r.local.apiAccepted||!r.remote.apiAccepted)why="zero_api_accepted";else if(lossPermille(r,true)<0||lossPermille(r,false)<0)why="invalid_counts";w.text(why);w.number(r.local.macTelemetryValid);w.number(r.remotePresent?r.remote.macTelemetryValid:-1);return w.finish();
}
} // namespace wifi_radio_test
